"""Abstract base repository providing common CRUD operations over a SQLite table.

Concrete repositories operate on a shared per-request sqlite3.Connection
(passed in at construction time, e.g. from Flask's `g`) rather than opening
their own connection, so they participate in the same transaction as the
rest of the request.
"""

from abc import ABC, abstractmethod


class BaseRepository(ABC):
    @property
    @abstractmethod
    def table_name(self):
        """Name of the SQLite table this repository operates on."""

    def __init__(self, db):
        self.db = db

    def get_by_id(self, id_):
        return self.db.execute(
            f"SELECT * FROM {self.table_name} WHERE id = ?", (id_,)
        ).fetchone()

    def list_all(self, where=None, params=(), order_by=None):
        query = f"SELECT * FROM {self.table_name}"
        if where:
            query += f" WHERE {where}"
        if order_by:
            query += f" ORDER BY {order_by}"
        return self.db.execute(query, params).fetchall()

    def delete(self, id_):
        self.db.execute(f"DELETE FROM {self.table_name} WHERE id = ?", (id_,))
        self.db.commit()

"""Repository for the users table."""

from base_repository import BaseRepository


class UserRepository(BaseRepository):
    table_name = "users"

    def get_by_username(self, username):
        return self.db.execute(
            "SELECT * FROM users WHERE username = ?", (username,)
        ).fetchone()

    def create(self, username, password_hash, email, created_at):
        cursor = self.db.execute(
            "INSERT INTO users (username, password_hash, email, created_at) VALUES (?, ?, ?, ?)",
            (username, password_hash, email, created_at),
        )
        self.db.commit()
        return self.get_by_id(cursor.lastrowid)

"""Repository for the tasks table.

SQLite's INTEGER PRIMARY KEY without AUTOINCREMENT can still reuse ids after
deletes, so task ids are assigned manually from a counter persisted in a
dedicated `counters` table rather than relying on SQLite's rowid behavior.
That id allocation is owned by this repository, alongside task creation.
"""

from base_repository import BaseRepository


class TaskRepository(BaseRepository):
    table_name = "tasks"

    def _next_id(self):
        self.db.execute("BEGIN IMMEDIATE")
        row = self.db.execute("SELECT value FROM counters WHERE name = 'task_id'").fetchone()
        next_id = row["value"]
        self.db.execute("UPDATE counters SET value = ? WHERE name = 'task_id'", (next_id + 1,))
        return next_id

    def create(self, title, status, created_at, owner_id):
        task_id = self._next_id()
        self.db.execute(
            "INSERT INTO tasks (id, title, status, created_at, owner_id) VALUES (?, ?, ?, ?, ?)",
            (task_id, title, status, created_at, owner_id),
        )
        self.db.commit()
        return self.get_by_id(task_id)

    def list_by_owner(self, owner_id):
        return self.db.execute(
            "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC, id DESC",
            (owner_id,),
        ).fetchall()

    def get_by_id_and_owner(self, task_id, owner_id):
        return self.db.execute(
            "SELECT * FROM tasks WHERE id = ? AND owner_id = ?",
            (task_id, owner_id),
        ).fetchone()

    def update(self, task_id, owner_id, title, status):
        self.db.execute(
            "UPDATE tasks SET title = ?, status = ? WHERE id = ? AND owner_id = ?",
            (title, status, task_id, owner_id),
        )
        self.db.commit()
        return self.get_by_id(task_id)

